def test_ttl_cache_default_ttl():
    import cachetools.func

    @cachetools.func.ttl_cache
    def my_func(n):
        return n

    # Access the underlying cache object via the .cache attribute
    underlying_cache = my_func.cache
    assert underlying_cache.ttl == 600, f"Expected default TTL of 600, got {underlying_cache.ttl}"

def test_rr_cache_default_maxsize_is_128():
    import cachetools.func

    cached = cachetools.func.rr_cache(lambda n: n)
    assert cached.cache_parameters()["maxsize"] == 128, (
        f"Expected default maxsize of 128, got {cached.cache_parameters()['maxsize']}"
    )
